with filtered_shipments as (select * from shipments where cost is null and status not in ('LOST', 'DELIVERED')), status_group_summary as (select case when status in ('LOST', 'RETURNED') then 'tier_1' else 'other' end as status_group, case when carrier in ('Flash', 'UPS') then 'core' else 'other' end as carrier_group, min(delivered_date) as min_delivered_date, sum(case when status = 'DELIVERED' then cost else 0 end) as delivered_cost from filtered_shipments group by case when status in ('LOST', 'RETURNED') then 'tier_1' else 'other' end, case when carrier in ('Flash', 'UPS') then 'core' else 'other' end) select status_group, carrier_group, min_delivered_date, delivered_cost from status_group_summary where delivered_cost >= 67;
